              "type": "string",
              "description": "下一条日历安排地点",
              "sampleValue": "科技园 B 座"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_car.png",
      "description": "汽车/打车图标，适合用于雨天打车场景的主视觉识别。"
    }
  ]
}

